function normalizeSlug(slug: string): string {
  return slug.trim().replace(/^\/+|\/+$/g, "").toLowerCase();
}

function lookup(map: Record<string, string>, slug: string): string | undefined {
  const key = normalizeSlug(slug);
  return map[key] || map[key.replace(/^custom-/, "")] || map[`custom-${key}`];
}

export function getCategoryMetaTitle(slug: string): string | undefined {
  return lookup(CATEGORY_META_TITLES, slug);
}

export function getProductMetaTitle(slug: string): string | undefined {
  return lookup(PRODUCT_META_TITLES, slug);
}

export function getCategoryMetaDescription(slug: string): string | undefined {
  return lookup(CATEGORY_META_DESCRIPTIONS, slug);
}

export function getProductMetaDescription(slug: string): string | undefined {
  return lookup(PRODUCT_META_DESCRIPTIONS, slug);
}
